-- Mensaje 113 · historia_larga y curriculum no cobran dos veces el mismo hecho (G66). El Cerebro no cambia.
UPDATE public.reglas SET resumen = $v$Alargarse: cada frase de más gasta la atención recién ganada y suena a discurso. LA PRUEBA: ¿la historia breve trae frases que no contestan quién eres, qué estás haciendo ni por qué estás ahí —la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto—? Una frase que explica el porqué es parte de esa pieza: no es de más. Si lo que sobra es presumir la empresa (años, premios, tamaño, catálogo o certificaciones) y el nodo lo califica aparte con story.kill_curriculum, esa falla lo cubre: el mismo hecho no se cobra dos veces.$v$, updated_at = now() WHERE id = 'story.kill' AND resumen = $v$Alargarse: cada frase de más gasta la atención recién ganada y suena a discurso. LA PRUEBA: ¿la historia breve trae frases que no contestan quién eres, qué estás haciendo ni por qué estás ahí —la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto—? Una frase que explica el porqué es parte de esa pieza: no es de más.$v$;
UPDATE public.reglas SET resumen = $v$Historia breve inflada con credenciales. LA PRUEBA: ¿el vendedor presume su empresa —años, premios, tamaño, catálogo o certificaciones— en lugar de decir quién es él y por qué está ahí?$v$, updated_at = now() WHERE id = 'story.kill_curriculum' AND resumen = $v$Historia breve inflada con credenciales. LA PRUEBA: ¿el vendedor habla de los años, premios, tamaño o catálogo de su empresa en lugar de quién es él y por qué está ahí?$v$;
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 El espejo es progresivo: el cliente no corta de golpe, se va apagando conforme la historia se alarga. Ensena la consecuencia real de perder la atencion.", "scope": {"skills_in_focus": ["story.historia_breve", "story.brevedad", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a preguntar quien soy.\n\nCuenta cuantas frases uso: tres. Quien soy, por que estoy aqui, y una pregunta que le devuelve la palabra.\n\nFijate en lo que NO digo: no cuento la historia de mi empresa, no enumero productos, no doy fechas ni cifras. Todo eso viene despues, y solo si el lo pide.", "first_message": "Soy Emilio, ando trabajando con los negocios de esta zona. Me tocaba pasar por aqui y quise conocer el suyo.\n\nCuenteme, cuanto tiempo lleva con el?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. La conversacion arranco bien y acabas de preguntarle al vendedor quien es. TU REGLA PRINCIPAL: reaccionas al LARGO y a la RELEVANCIA de su respuesta. Si contesta breve (dos o tres frases) y te dice algo que a TI te importa, te relajas, contestas con gusto y sigues la conversacion. Si se extiende — historia de la empresa, anos en el mercado, lista de productos, certificaciones, mas de cuatro frases seguidas — empiezas a desconectarte: contestas con ajam, miras a otro lado, dices que andas ocupado. No lo cortas de golpe, te vas apagando. Si te habla puro de el y de su empresa sin conectar con tu negocio, contestas cortes pero sin interes. Si termina con una pregunta abierta, la contestas con gusto. Si termina sin pregunta, te quedas callado esperando, y el silencio se siente incomodo. NUNCA preguntes por productos ni precios en este ejercicio. Responde en 1 o 2 frases.", "objective": "El vendedor responde quien es en dos o tres frases, conectando su presencia con algo que le importe al cliente, y devuelve la palabra con una pregunta. El scope se cubre cuando el cliente se relaja y sigue la conversacion por su propia voluntad."}, "closing": {"message": "Eso es una historia breve. Quince segundos, dos piezas y un gancho. El cliente ya sabe con quien habla y sigue contigo, que es exactamente lo que este paso tiene que lograr. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como te presentas. Vamos al desglose y te digo que le sobraba o que le faltaba."}}, "version": "2.0.2", "i_do_type": "demo", "failure_criteria": [{"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "Mete frases que no contestan quien es, que hace ni por que esta ahi: da detalles de mas o le da vueltas. Si lo que sobra es presumir la empresa, eso es curriculum y no se cobra aqui otra vez. El cliente se desconecta."}, {"id": "curriculum", "regla_id": "story.kill_curriculum", "severity": "major", "description": "Presume la empresa —anos, premios, tamano, catalogo o certificaciones— en lugar de decir quien es y por que esta ahi. Suena a discurso y el cliente se desconecta."}, {"id": "sin_gancho", "regla_id": "story.cierra_con_afirmacion", "severity": "minor", "description": "Termina la historia sin devolver la palabra. Deja al cliente sin nada que contestar y la conversacion se queda en el aire.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Aprovecha la presentacion para meter producto, promocion o motivo de venta. La historia breve dice quien eres, no que vendes."}], "success_criteria": [{"id": "story.historia_breve", "weight": 0.4, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, de donde viene, y el motivo de la visita en terminos humanos. Las dos piezas presentes."}, {"id": "story.brevedad", "weight": 0.35, "regla_id": "story.kiss", "description": "Corta: quien es, que hace y por que esta ahi, cada pieza una vez. Sin historia de la empresa, anos en el mercado, lista de productos ni certificaciones. Se mide por piezas, no por frases: explicar el porque es parte de esa pieza."}, {"id": "story.relevancia_cliente", "weight": 0.25, "regla_id": "story.pregunta_despues", "description": "Conecta su presencia con algo que le importe al cliente, no consigo mismo. Y devuelve la palabra con una pregunta abierta en lugar de quedarse esperando."}]}$g$::jsonb WHERE id = '2.1' AND practice_script->>'version' = '2.0.1';
DO $chk$ BEGIN
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.kill') IS DISTINCT FROM $v$Alargarse: cada frase de más gasta la atención recién ganada y suena a discurso. LA PRUEBA: ¿la historia breve trae frases que no contestan quién eres, qué estás haciendo ni por qué estás ahí —la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto—? Una frase que explica el porqué es parte de esa pieza: no es de más. Si lo que sobra es presumir la empresa (años, premios, tamaño, catálogo o certificaciones) y el nodo lo califica aparte con story.kill_curriculum, esa falla lo cubre: el mismo hecho no se cobra dos veces.$v$ THEN RAISE EXCEPTION 'la regla story.kill no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.kill_curriculum') IS DISTINCT FROM $v$Historia breve inflada con credenciales. LA PRUEBA: ¿el vendedor presume su empresa —años, premios, tamaño, catálogo o certificaciones— en lugar de decir quién es él y por qué está ahí?$v$ THEN RAISE EXCEPTION 'la regla story.kill_curriculum no quedó'; END IF;
  IF (SELECT practice_script->>'version' FROM public.nodes WHERE id = '2.1') IS DISTINCT FROM '2.0.2' THEN RAISE EXCEPTION 'el guion del 2.1 no quedó'; END IF;
END $chk$;
